	chapters = {
		{
			title = "A Pedra de Juramento",
			hint = "Jure ajudar o prisioneiro libertado.",
			text = [=[Belnistrasz deu uma pedra a seus salvadores e pediu que a devolvessem a ele se quisessem se juntar a ele. Eles devolveram. Ele não lhes escondeu o perigo. O trabalho à frente era difícil, disse, mas, se mantivessem a mente na tarefa, poderiam vencer.]=],
