			title = "O Ídolo se Apaga",
			hint = [=[Proteja Belnistrasz enquanto ele realiza seu ritual no ídolo.]=],
			text = [=[O ídolo perto da entrada era um forno hediondo, e Belnistrasz podia selá-lo para sempre, mas seu ritual o deixaria indefeso. Seus companheiros contiveram os {link:death-s-head}Pontafatal{/link} por cinco longos minutos enquanto ele anunciava o tempo. Por fim, as chamas se apagaram. Belnistrasz tinha sumido, e restava apenas um braseiro aceso onde ele estivera. Em suas chamas surgiu um grande dragão vermelho de asas imensas. Sua voz, agora mais grave, agradeceu aos mortais que haviam renovado sua fé neles.]=],
		},
	},
	bonds = {
		{ id = "plaguemaw-the-rotting", name = "Plaguemaw, o Pútrido", note = "veio impedir seu ritual" },
		{ id = "henry-stern", name = "Henry Stern", note = "companheiro de cativeiro" },
		{ id = "amnennar-the-coldbringer", name = "Amnennar the Coldbringer", note = "o inimigo de tudo o que ele defende" },
	},
})

Translate("ptBR", "amnennar-the-coldbringer", {
	title = "Amnennar the Coldbringer",
	subtitle = "Lich do Urzal dos Mortos",
	found = "O topo da Espiral de Espinhos, no fundo do Urzal dos Mortos",
