	aliases = { "Amnennar", "o Coldbringer" },
	sections = {
		{
			title = "Resumo",
			text = [=[Amnennar the Coldbringer é um lich, servo do Lich Rei e senhor do {link:razorfen-downs}Urzal dos Mortos{/link}. Ele governa os {link:death-s-head}Pontafatal{/link} do alto de uma grande espiral de espinhos, entre fogos frios e espíritos inquietos. Dizem que sua mente é tão vasta que ele guia os javatuscos em tudo o que fazem. Quando ameaçado, ele se diz a mão do Lich Rei e convoca os mortos congelados para o seu lado.]=],
		},
		{
			title = "Importância",
			text = [=[Amnennar deu ao {link:scourge}Flagelo{/link} uma fortaleza em {link:kalimdor}Kalimdor{/link}. Por meio dele, a praga alcança um povo que nunca a conhecera, e a guerra que pôs fim a {link:lordaeron}Lordaeron{/link} atravessa o mar. Dizem que ele lutou com o Flagelo na {link:battle-of-mount-hyjal}Batalha do Monte Hyjal{/link} e que o Lich Rei então lhe ordenou que ficasse para trás e espalhasse seu poder. Os javatuscos, expulsos de suas terras, estavam prontos para ouvir um senhor que lhes prometia domínio sobre a morte.]=],
		},
		{
			title = "Feitos",
			text = [=[• Fez do labirinto sagrado dos javatuscos um bastião dos mortos-vivos.
• Ergueu os mortos do Urzal como esqueletos e guerreiros ressequidos.
• Submeteu os {link:death-s-head}Pontafatal{/link} à sua vontade.]=],
		},
	},
	chapters = {
		{
			title = "Tragam a Luz",
			hint = "Atenda ao chamado do Arcebispo para destruir o lich.",
			text = [=[Em {link:stormwind-city}Ventobravo{/link}, o {link:archbishop-benedictus}Arcebispo Benedictus{/link} soube que os javatuscos de um labirinto de espinhos nos {link:the-barrens}Sertões{/link} haviam feito um pacto com o {link:scourge}Flagelo{/link} e que um lich os governava. Ele não esperou o mal crescer. Enviou campeões da Luz para acabar com a união pela raiz.]=],
		},
		{
			title = "Tragam o Fim",
			hint = "Leve o crânio do Coldbringer de volta à Cidade Baixa.",
			text = [=[A princípio, os {link:forsaken}Renegados{/link} não viam {link:razorfen-downs}o Urzal dos Mortos{/link} como ameaça. Relatórios posteriores os fizeram mudar de ideia. {red:andrew-brownell}Andrew Brownell{/red}, dos {link:royal-apothecary-society}boticários{/link}, acreditava que Amnennar estava ligado em pensamento ao próprio {link:ner-zhul}Ner'zhul{/link} e que esse laço precisava ser cortado. Ele pediu o crânio do lich.]=],
		},
	},
	mentions = {
		{
			text = [=[Uma Hoste do Mal, as fileiras crescentes do {link:razorfen-downs}Urzal dos Mortos{/link}]=],
		},
	},
	bonds = {
		{ id = "belnistrasz", name = "Belnistrasz", note = "inimigo de tudo o que ele constrói" },
		{ id = "mordresh-fire-eye", name = "Mordresh Fire Eye", note = "seu servo" },
		{ id = "glutton", name = "Glutão", note = "seu servo" },
		{ id = "ambassador-malcin", name = "Embaixador Malcin", note = "outro servo do Lich Rei" },
	},
})

Translate("ptBR", "tuten-kash", {
