		{
			title = "Resumo",
			text = [=[O Embaixador Malcin é um emissário morto-vivo do {link:scourge}Flagelo{/link} que espera do lado de fora dos espinhos do {link:razorfen-downs}Urzal dos Mortos{/link}. Em vida, era humano, um diplomata a serviço de {link:lordaeron}Lordaeron{/link}. A praga o transformou, e agora ele fala pelo Lich Rei. Escreveu com cortesia à anciã que governa o {link:razorfen-kraul}Urzal dos Tuscos{/link}, oferecendo-lhe os {link:the-barrens}Sertões{/link} e as terras além, desde que ela deixasse o Flagelo agir livremente ali. Ao redor dele, javatuscos se reúnem para implorar por seu poder e recebem a morte-vida.]=],
		},
		{
			title = "Importância",
			text = [=[Malcin é a voz do pacto do {link:scourge}Flagelo{/link} com os javatuscos. Sua carta alertou os {link:forsaken}Renegados{/link} de que o Lich Rei estava estendendo a mão para {link:kalimdor}Kalimdor{/link}, e {link:varimathras}Varimathras{/link} o queria morto.]=],
		},
		{
			title = "Feitos",
			text = [=[• Ofereceu uma aliança aos javatuscos do {link:razorfen-kraul}Urzal dos Tuscos{/link}.
• Concede a morte-vida aos javatuscos que a buscam.]=],
		},
	},
	mentions = {
		{ text = "Uma {link:alliance}Aliança{/link} Profana, sua carta" },
		{ text = "Uma Hoste do Mal" },
	},
	bonds = {
		{ id = "amnennar-the-coldbringer", name = "Amnennar the Coldbringer", note = "outro servo do Lich Rei" },
		{ id = "myriam-moonsinger", name = "Myriam Moonsinger", note = "vigia-o" },
	},
})

Translate("ptBR", "death-s-head", {
	title = "Pontafatal",
	aliases = { "tribo Pontafatal", "culto Pontafatal" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Pontafatal são os sumos sacerdotes dos {link:quilboar}javatuscos{/link}, guardiões dos cemitérios do {link:razorfen-downs}Urzal dos Mortos{/link}. Eles se voltaram para o {link:scourge}Flagelo{/link}. Sob o lich {link:amnennar-the-coldbringer}Amnennar the Coldbringer{/link}, servem à morte-vida no lugar mais sagrado de seu povo, e muitos de seus guerreiros agora andam como cadáveres ressequidos.]=],
		},
		{
			title = "O Pacto",
			text = [=[Ninguém fora do Urzal sabe toda a verdade de como começou. O {link:scourge}Flagelo{/link} enviou um emissário, o {link:ambassador-malcin}Embaixador Malcin{/link}, que ofereceu aos javatuscos os {link:the-barrens}Sertões{/link} e mais em troca de sua ajuda. {link:varimathras}Varimathras{/link} acredita que a anciã do {link:razorfen-kraul}Urzal dos Tuscos{/link} se manteve à parte do acordo. Os sacerdotes do {link:razorfen-downs}Urzal dos Mortos{/link}, não. Alguns de sua tribo ficaram assustadoramente fortes e mostram as marcas da praga. A elfa noturna {link:myriam-moonsinger}Myriam Moonsinger{/link} viu javatuscos saírem das sombras todos os dias para implorar ao emissário por mais poder.]=],
		},
		{
			title = "A Ordem",
			text = [=[Sacerdotes, necromantes, geomantes e cultistas Pontafatal servem ao lich ao lado de guerreiros e tecespinhos javatuscos vivos. {link:quilboar}Javatuscos{/link} ressequidos, javalis de guerra e esqueletos enchem suas fileiras. Entre eles estão {link:ragglesnout}Ragglesnout{/link}, que ainda vive, e {link:plaguemaw-the-rotting}Plaguemaw, o Pútrido{/link}, que não vive. Seus cativos são mantidos em cercados perto da entrada, e os que não são resgatados são queimados e devorados diante do ídolo.]=],
		},
	},
})
